export const MUSIC_PLATFORMS={youtubeMusic:{label:'YouTube Music',hosts:['music.youtube.com']},youtube:{label:'YouTube',hosts:['youtube.com','www.youtube.com','youtu.be']},spotify:{label:'Spotify',hosts:['open.spotify.com']},appleMusic:{label:'Apple Music',hosts:['music.apple.com']},soundcloud:{label:'SoundCloud',hosts:['soundcloud.com','www.soundcloud.com','on.soundcloud.com']},n64:{label:'Nickel 64',hosts:null}};
export function musicLinks(values={}){const links={};for(const [key,raw] of Object.entries(values)){if(!(key in MUSIC_PLATFORMS))throw new Error('Unknown music platform.');if(!raw?.trim())continue;let url;try{url=new URL(raw.trim());}catch{throw new Error(`Enter a valid ${MUSIC_PLATFORMS[key].label} link.`);}const platform=MUSIC_PLATFORMS[key];if(url.protocol!=='https:'||url.username||url.password||url.port||raw.length>2000||(platform.hosts&&!platform.hosts.includes(url.hostname)))throw new Error(`Use an HTTPS ${platform.label} link${platform.hosts?' from that platform':''}.`);links[key]=url.href;}return links;}
const icons={youtubeMusic:'<circle cx="12" cy="12" r="11" fill="#ff4040"/><circle cx="12" cy="12" r="7" fill="none" stroke="white"/><path d="m10 8 6 4-6 4z" fill="white"/>',youtube:'<rect x="1" y="4" width="22" height="16" rx="5" fill="#ff4040"/><path d="m10 8 6 4-6 4z" fill="white"/>',spotify:'<circle cx="12" cy="12" r="11" fill="#1ed760"/><path d="M6 9q6-3 12 1M7 13q5-2 10 1M8 17q4-2 8 0" fill="none" stroke="#111315" stroke-width="2" stroke-linecap="round"/>',appleMusic:'<rect x="1" y="1" width="22" height="22" rx="5" fill="#fa526b"/><path d="M10 17V7l8-2v10M10 9l8-2" fill="none" stroke="white" stroke-width="2"/><ellipse cx="8" cy="18" rx="3" ry="2" fill="white"/><ellipse cx="16" cy="16" rx="3" ry="2" fill="white"/>',soundcloud:'<path d="M2 13v6M5 10v9M8 7v12" stroke="#ff8800" stroke-width="2"/><path d="M11 19V7q7-2 7 6c6-1 6 6 0 6z" fill="#ff8800"/>',n64:'<rect x="1" y="1" width="22" height="22" rx="5" fill="#d9ff60"/><text x="12" y="15" text-anchor="middle" font-family="Arial" font-size="9" font-weight="900" fill="#111315">N64</text>'};
export function renderMusicLinks(song,escape){let links;try{links=musicLinks(song.links||{});}catch{return '';}const content=Object.entries(links).map(([key,url])=>`<a class="music-icon" href="${escape(url)}" target="_blank" rel="noopener noreferrer" title="Listen on ${MUSIC_PLATFORMS[key].label}" aria-label="Listen to ${escape(song.title)} on ${MUSIC_PLATFORMS[key].label}"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[key]}</svg></a>`).join('');return content?`<span class="music-links">${content}</span>`:'';}
